SELECT 
FROM expense
WHERE trip_id = #{tripId} AND client_uuid = #{clientUuid}

SELECT

FROM expense
WHERE trip_id = #{tripId} AND deleted_at IS NULL
AND (visibility = 'trip' OR created_by_member_id = #{currentMemberId})

    AND (paid_by_member_id = #{memberId} OR EXISTS
    (SELECT 1 FROM expense_split s WHERE s.expense_id = expense.id AND s.member_id = #{memberId}))

AND currency = #{currency}
AND category = #{category}

    AND occurred_at BETWEEN #{occurredFrom} AND #{occurredTo}

ORDER BY occurred_at DESC, id DESC

SELECT expense_id, member_id, amount_minor FROM expense_split WHERE expense_id IN
#{expenseId}
ORDER BY member_id
